{
  "extractions": [
    {
      "unit": "F001",
      "unit_attributes": {
        "statement": "Review notice (RN) means a written request for missing records.",
        "actor": null,
        "actor_quote": null,
        "kind": "definition",
        "modality": "not_stated"
      }
    },
    {
      "unit": "F002",
      "unit_attributes": {
        "statement": "Service receipt (SR) means an acknowledgement that records were received; it is not an approval.",
        "actor": null,
        "actor_quote": null,
        "kind": "definition",
        "modality": "not_stated"
      }
    },
    {
      "unit": "F003",
      "unit_attributes": {
        "statement": "Applicants must return the RN within ten days unless a reviewer extends the deadline.",
        "actor": "Applicants",
        "actor_quote": "Applicants",
        "kind": "requirement",
        "modality": "must",
        "modality_quote": "must"
      }
    },
    {
      "unit": "F004",
      "unit_attributes": {
        "statement": "Reviewers may extend the deadline by five days only with a supervisor's approval.",
        "actor": "Reviewers",
        "actor_quote": "Reviewers",
        "kind": "permission",
        "modality": "may",
        "modality_quote": "may"
      }
    },
    {
      "unit": "F005",
      "unit_attributes": {
        "statement": "Clerks must issue an SR when an RN is received.",
        "actor": "Clerks",
        "actor_quote": "Clerks",
        "kind": "requirement",
        "modality": "must",
        "modality_quote": "must",
        "logic_quote": "F005"
      }
    },
    {
      "unit": "F006",
      "unit_attributes": {
        "statement": "A supervisor's name appears on the RN.",
        "actor": null,
        "actor_quote": null,
        "kind": "statement",
        "modality": "not_stated"
      }
    },
    {
      "unit": "F007",
      "unit_attributes": {
        "statement": "You must keep a copy of the SR.",
        "actor": "You",
        "actor_quote": "You",
        "kind": "requirement",
        "modality": "must",
        "modality_quote": "must"
      }
    },
    {
      "unit": "F008",
      "unit_attributes": {
        "statement": "Files must be retained for two years.",
        "actor": null,
        "actor_quote": null,
        "kind": "requirement",
        "modality": "must",
        "modality_quote": "must"
      }
    },
    {
      "unit": "F009",
      "unit_attributes": {
        "statement": "Storage may be unavailable during maintenance.",
        "actor": null,
        "actor_quote": null,
        "kind": "statement",
        "modality": "possible",
        "modality_quote": "may"
      }
    },
    {
      "unit": "F010",
      "unit_attributes": {
        "statement": "XYZ is an external reference code whose meaning is not supplied here.",
        "actor": null,
        "actor_quote": null,
        "kind": "statement",
        "modality": "not_stated"
      }
    }
  ]
}
